import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { Router } from '@angular/router';
import Chart from 'chart.js/auto';
import 'chartjs-plugin-datalabels';

@Component({
  selector: 'app-cwsn-bar-chart',
  templateUrl: './cwsn-bar-chart.page.html',
  styleUrls: ['./cwsn-bar-chart.page.scss'],
})
export class CwsnBarChartPage implements OnInit {

  @ViewChild('barCanvas') barCanvas: ElementRef;
  barChart: any;

  constructor(private router: Router,) { }

  ngOnInit() {
  }

  ionViewDidEnter(){
    this.createBarChart();
  }

  createBarChart() {
    const pluginOptions = {
      datalabels: {
        anchor: 'start', 
        align: 'start',
        display: true 
      },
      title: {
        display: true,
        text: 'Chart.js Bar Chart - Stacked'
      },
    };

    this.barChart = new Chart(this.barCanvas.nativeElement, {
      type: 'bar',
      data: {
        labels: ['Sensory', 'Motor & Mobility', 'Cognition & Sensory Integration', 'Communication & Social Skill', 'Assistive Device'],
        datasets: [{
          label: 'Archived',
          data: [12, 55, 3, 65, 2, 3],
          backgroundColor: '#8B66B3',
          borderWidth: 1
        }, {
          label: 'Need Intervention',
          data: [7, 11, 5, 8, 83, 6],
          backgroundColor: '#E10B91',
          borderWidth: 1
        }, {
          label: 'Total Goals',
          data: [0, 0, 0, 0, 0, 0],
          backgroundColor: '#15B10A',
          borderWidth: 1
        }]
      },
      options: {
        // plugins: pluginOptions,
        interaction: {
          intersect: false,
        },
        responsive: true,
        scales: {
          x: {
            stacked: true
          },
          y: {
            stacked: true
          }
        },
      }
    });
  }

  navigateBack(){
    this.router.navigate(['/tabs/home'])
  }

}
